#!/usr/bin/env node
/*
 * import-symptom-cfs.js
 *
 * Author-side importer for the Symptom Content Fragments generated by
 * generate-symptom-cfs.js. Creates one CF per content-fragments/fragments/<slug>.json
 * in the DAM against the 'symptom' model, via the AEM Assets HTTP API.
 *
 * ⚠️ Requires WRITE access to the AEM author instance. This project's injected
 *    credentials target admin.hlx.page / Document Authoring, NOT the Sling-auth
 *    author instance, so this script will 401 unless run in an environment that
 *    can authenticate to author (e.g. with AEM_AUTHOR_AUTH set to a valid
 *    "Basic base64(user:pass)" or "Bearer <token>" for that instance).
 *
 * The CF model must exist first (import content-fragments/model/symptom.model.cfm.json
 * to /conf/creid-play/settings/dam/cfm/models/symptom).
 *
 * Usage:
 *   AEM_AUTHOR=https://author-p218415-e2256034.adobeaemcloud.com \
 *   AEM_AUTHOR_AUTH="Basic <base64>" \
 *   node tools/cf/import-symptom-cfs.js [--dry-run] [--only <slug>]
 *
 * Env:
 *   AEM_AUTHOR       author base URL (default: the p218415 instance)
 *   AEM_AUTHOR_AUTH  Authorization header value for author (Basic/Bearer)
 */

const fs = require('fs');
const path = require('path');

const REPO = path.resolve(__dirname, '..', '..');
const FRAG_DIR = path.join(REPO, 'content-fragments', 'fragments');

const AUTHOR = process.env.AEM_AUTHOR || 'https://author-p218415-e2256034.adobeaemcloud.com';
const AUTH = process.env.AEM_AUTHOR_AUTH || '';
const DRY = process.argv.includes('--dry-run');
const onlyIdx = process.argv.indexOf('--only');
const ONLY = onlyIdx !== -1 ? process.argv[onlyIdx + 1] : null;

// DAM parent folder for the fragments (must match generator CF_DAM_ROOT).
const CF_DAM_ROOT = '/content/dam/aem-xwalk-llmapps/symptoms';
const CF_MODEL_PATH = '/conf/creid-play/settings/dam/cfm/models/symptom';

async function createFragment(frag) {
  // AEM Assets API: create a content fragment as a sub-asset of the parent folder.
  // POST /api/assets/<parent>  with Content-Type application/json and a cq:model body.
  const parent = CF_DAM_ROOT.replace(/^\/content\/dam/, '');
  const url = `${AUTHOR}/api/assets${parent}/*`;
  const body = {
    properties: {
      'cq:model': CF_MODEL_PATH,
      title: frag.title,
      name: frag.name,
      elements: Object.fromEntries(
        Object.entries(frag.fields).map(([k, v]) => [k, { value: v }]),
      ),
    },
  };

  if (DRY) {
    console.log(`[dry-run] would POST ${url}  (${frag.name}, ${JSON.stringify(body).length} bytes)`);
    return { ok: true, dry: true };
  }

  const res = await fetch(`${AUTHOR}/api/assets${parent}/${frag.name}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      ...(AUTH ? { Authorization: AUTH } : {}),
    },
    body: JSON.stringify(body),
  });
  return { ok: res.ok, status: res.status, text: res.ok ? '' : await res.text() };
}

(async () => {
  if (!DRY && !AUTH) {
    console.error('No AEM_AUTHOR_AUTH set. Re-run with --dry-run to preview, or set credentials.');
    process.exit(2);
  }
  let files = fs.readdirSync(FRAG_DIR).filter((f) => f.endsWith('.json'));
  if (ONLY) files = files.filter((f) => f === `${ONLY}.json`);

  let ok = 0; let fail = 0;
  for (const f of files) {
    const frag = JSON.parse(fs.readFileSync(path.join(FRAG_DIR, f), 'utf8'));
    try {
      const r = await createFragment(frag);
      if (r.ok) { ok++; console.log(`✓ ${frag.name}${r.dry ? ' (dry)' : ''}`); }
      else { fail++; console.error(`✗ ${frag.name}: HTTP ${r.status} ${r.text.slice(0, 200)}`); }
    } catch (e) {
      fail++; console.error(`✗ ${frag.name}: ${e.message}`);
    }
  }
  console.log(`\nDone. Success: ${ok}, Failures: ${fail}, Total: ${files.length}`);
})();
